#ifndef APP_H
#define APP_H

/*
 * Application layer. main.c (generated by CubeMX) only calls App_Init() once
 * after the peripherals are initialised and App_Update() from the main loop,
 * so regenerating the CubeMX code does not touch the application logic.
 */

void App_Init(void);
void App_Update(void);

/* Forces the motor PWM output low immediately, without relying on any
 * application state. Safe to call from fault handlers. */
void App_EmergencyOutputOff(void);

#endif /* APP_H */
